def weighted_choice(items, weights):
    total = sum(weights)
    r = random.uniform(0, total)

    upto = 0
    for item, weight in zip(items, weights):
        if upto + weight >= r:
            return item
        upto += weight

def Generate_Word():

    word = []

    word_len = random.randint(4, 16)

    # First letter
    word.append(weighted_choice(alphabet, Start_Letter))

    for i in range(word_len - 1):

        for x in range(len(alphabet)):

            if word[i] == alphabet[x]:

                # Pick next letter using weighted choice
                word.append(
                    weighted_choice(
                        alphabet,
                        alphabet_lists[x]
                    )
                )

                break

    return ''.join(word)




